practice.solution:
const a = 3;
const b = 10;
const op = "gap";
let result;

switch (op) {
  case "+":
    result = a + b;
    break;
  case "-":
    result = a - b;
    break;
  case "*":
    result = a * b;
    break;
  case "/":
    result = a / b;
    break;
  case "avg": {
    const total = a + b;
    result = total / 2;
    break;
  }
  case "gap": {
    let diff = a - b;
    if (diff < 0) {
      diff = -diff;
    }
    result = diff;
    break;
  }
  default:
    console.log("Unknown operator");
}

if (result !== undefined) {
  console.log(`${a} ${op} ${b} = ${result}`);
}
